mkdir -p /tmp/arxtools /tmp/arxdl && cat > /tmp/arxtools/arxq.py << 'EOF'
import sys, re, urllib.request, urllib.parse, time, html
def q(query, n=100):
    url = "https://export.arxiv.org/api/query?" + urllib.parse.urlencode({"search_query": query, "start": 0, "max_results": n, "sortBy": "submittedDate", "sortOrder": "descending"})
    for attempt in range(3):
        try:
            d = urllib.request.urlopen(url, timeout=60).read().decode()
            break
        except Exception as ex:
            time.sleep(3)
    else:
        print("FAIL", query); return []
    tot = re.search(r'<opensearch:totalResults>(\d+)<', d)
    ents = d.split('<entry>')[1:]
    out = []
    for e in ents:
        t = html.unescape(re.sub(r'\s+', ' ', re.search(r'<title>(.*?)</title>', e, re.S).group(1)))
        i = re.search(r'<id>(.*?)</id>', e).group(1).split('/abs/')[-1]
        p = re.search(r'<published>(.*?)</published>', e).group(1)[:10]
        out.append((p, i, t))
    print(f"## {query}  [total={tot.group(1) if tot else '?'}]")
    for p, i, t in out:
        print(p, i, t)
    return out
if __name__ == "__main__":
    for qq in sys.argv[1:]:
        q(qq)
        time.sleep(3)
EOF
python3 -I /tmp/arxtools/arxq.py 'abs:speculative AND abs:mamba' 'abs:speculative AND abs:"state space"' 'abs:speculative AND abs:"linear attention"' 'abs:speculative AND abs:hybrid AND abs:recurrent' 'abs:speculative AND abs:SSM' 'abs:speculative AND abs:RWKV' 'abs:speculative AND abs:"DeltaNet"'

